def f(g):
    H,W=len(g),len(g[0]); bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    res=[row[:] for row in g]
    dots={'1':(2,1),'2':(6,7),'6':(7,5),'3':(7,9)}
    moves={'1':(-1,2),'2':(0,-4),'6':(-6,0),'3':(3,0)}
    # step 1: mark dot positions, paint trails, build occupied set
    occ={(sr,sc):col for col,(sr,sc) in dots.items()}
    for col,(sr,sc) in dots.items():
        dr,dc=moves[col]; r_,c_=sr+dr,sc+dc
        while 0<=r_<H and 0<=c_<W:
            res[r_][c_]=5; occ[(r_,c_)]=None
            r_+=dr; c_+=dc
    # step 2: rays of 4 from start opposite velocity until blocked
    for col,(sr,sc) in dots.items():
        dd=(-moves[col][0],-moves[col][1]); rr,cc=sr+dd[0],sc+dd[1]
        while 0<=rr<H and 0<=cc<W and res[rr][cc]==0:
            res[rr][cc]=4; rr+=dd[0]; cc+=dd[1]
    # step 3: crossings of two straight dot paths -> 4-ray from crossing in direction sign-sum of velocities
    cols=sorted(dots)
    for i in range(len(cols)):
        for j in range(i+1,len(cols)):
            a,cola,dra=dots[cols[i]],moves[cols[i]]
            b,colb,dcb=dots[cols[j]],moves[cols[j]]
            A=[(a[0]+k*dra[0],a[1]+k*dra[1]) for k in range(H)]
            B=[(b[0]+t*dcb[0],b[1]+t*dcb[1]) for t in range(H)]
            inter=set(A)&set(B)
            if not inter: continue
            for (r,c) in list(inter):
                sgn=(max(sign(dra[0])+sign(dcb[0]), -1), max(sign(dra[1])+sign(dcb[1]), -1))
                rr,cc=r+sgn[0],c+sgn[1]
                while 0<=rr<H and 0<=cc<W and res[rr][cc]==0:
                    res[rr][cc]=4; rr+=sgn[0]; cc+=sgn[1]
    return res
