# Study pair structures: identify 'objects' (colors, bboxes) in inputs vs outputs.
def comps(g, bg=None):
    seen=set(); out=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            v=g[r][c]
            if (r,c) in seen or v==bg: continue
            stack=[(r,c)]; comp=[]
            while stack:
                y,x=stack.pop()
                if (y,x) in seen: continue
                seen.add((y,x)); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx]==v and (ny,nx) not in seen:
                        stack.append((ny,nx))
            out.append((v,sorted(comp)))
    return out
